if (!defined('ABSPATH')) { exit; }
function scwb_v880_backend_request($path,$method='GET',$body=null){$base=untrailingslashit((string)get_option('sc_workbench_backend_url','https://workbench-api.sustainablecatalyst.com'));$args=array('method'=>$method,'timeout'=>25,'headers'=>array('Accept'=>'application/json','Content-Type'=>'application/json'));if($body!==null){$args['body']=wp_json_encode($body);} $r=wp_remote_request($base.$path,$args);if(is_wp_error($r)){return array('ok'=>false,'error'=>$r->get_error_message());}$j=json_decode(wp_remote_retrieve_body($r),true);if(!is_array($j)){$j=array('ok'=>false,'error'=>'Invalid backend response');}$j['_httpStatus']=wp_remote_retrieve_response_code($r);return $j;}
function scwb_v880_status_shortcode(){ $r=scwb_v880_backend_request('/v880/status'); return '<pre class="scwb-v880-status">'.esc_html(wp_json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre>'; }
add_shortcode('sc_workbench_comparative_analysis_status','scwb_v880_status_shortcode');
function scwb_v880_compare_shortcode($atts=array()){$a=shortcode_atts(array('project'=>''),$atts);$project=sanitize_text_field($a['project']);$uid='scwb-v880-'.wp_generate_uuid4();ob_start(); ?>
<div id="<?php echo esc_attr($uid); ?>" class="scwb-v880" data-nonce="<?php echo esc_attr(wp_create_nonce('wp_rest')); ?>">
<header><div><small>SUSTAINABLE CATALYST WORKBENCH · V8.8.0</small><h3>Comparative Experiment &amp; Model Analysis</h3><p>Compare completed computational runs, parameters, outputs and provenance without automatic ranking or winner selection.</p></div><label>Project <input data-role="project" value="<?php echo esc_attr($project); ?>" placeholder="project-key"></label><button data-action="load" type="button">Load runs</button></header>
<div class="scwb-v880-body"><aside><h4>Completed runs</h4><div data-role="jobs"></div><button data-action="compare" type="button">Compare selected</button></aside><main><div data-role="status">Select at least two completed runs.</div><div class="scwb-v880-cards" data-role="cards"></div><section><h4>Result metrics</h4><div class="scwb-v880-table"><table><thead><tr data-role="metric-head"><th>Metric</th></tr></thead><tbody data-role="metrics"></tbody></table></div></section><section><h4>Pairwise deltas</h4><div data-role="pairs"></div></section></main></div>
<footer>Comparisons are descriptive analytical views. Workbench does not infer scientific validity, causal superiority, statistical significance, or a winning model.</footer>
</div>
<style>.scwb-v880{background:#090909;color:#ddd;border:1px solid #2a2a2a;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.scwb-v880 header{display:flex;gap:14px;align-items:end;justify-content:space-between;padding:14px;border-bottom:1px solid #252525}.scwb-v880 h3,.scwb-v880 h4{margin:3px 0 8px}.scwb-v880 small{color:#82c995}.scwb-v880 input,.scwb-v880 button{background:#111;color:#ddd;border:1px solid #3b3b3b;padding:7px}.scwb-v880 button{cursor:pointer}.scwb-v880-body{display:grid;grid-template-columns:280px 1fr;min-height:500px}.scwb-v880 aside{border-right:1px solid #252525;padding:12px}.scwb-v880 aside label{display:block;padding:6px 0;border-bottom:1px solid #202020;font-size:11px}.scwb-v880 main{padding:12px;min-width:0}.scwb-v880-cards{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.scwb-v880-card{border:1px solid #333;padding:9px;min-width:170px}.scwb-v880-card b{display:block}.scwb-v880-table{overflow:auto}.scwb-v880 table{border-collapse:collapse;width:100%;font-size:10px}.scwb-v880 th,.scwb-v880 td{padding:6px;border-bottom:1px solid #222;text-align:right}.scwb-v880 th:first-child,.scwb-v880 td:first-child{text-align:left}.scwb-v880-pair{border:1px solid #292929;padding:8px;margin:6px 0;font-size:10px}.scwb-v880 footer{padding:9px 12px;border-top:1px solid #252525;color:#888;font-size:9px}@media(max-width:800px){.scwb-v880-body{grid-template-columns:1fr}.scwb-v880 aside{border-right:0;border-bottom:1px solid #252525}}</style>
<script>(function(){const root=document.getElementById(<?php echo wp_json_encode($uid); ?>);if(!root)return;const rest=<?php echo wp_json_encode(esc_url_raw(rest_url('sc-workbench/v1/comparative-analysis/'))); ?>,nonce=root.dataset.nonce,$=s=>root.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const api=(path,method='GET',body=null)=>fetch(rest+path,{method,headers:{'Accept':'application/json','Content-Type':'application/json','X-WP-Nonce':nonce},body:body?JSON.stringify(body):undefined}).then(async r=>{const b=await r.json();if(!r.ok||b.ok===false)throw new Error(typeof b.detail==='string'?b.detail:(b.error||'Request failed'));return b;});function project(){return $('[data-role=project]').value.trim()}async function load(){if(!project())return;$('[data-role=status]').textContent='Loading…';try{const b=await api('jobs/'+encodeURIComponent(project()));$('[data-role=jobs]').innerHTML=(b.jobs||[]).map(j=>'<label><input type="checkbox" value="'+esc(j.jobId)+'"> '+esc(j.label||j.jobId)+'<br><small>'+esc(j.runtimeKind)+' · '+esc(j.status)+'</small></label>').join('');$('[data-role=status]').textContent=(b.jobCount||0)+' completed runs available';}catch(e){$('[data-role=status]').textContent='Error: '+e.message}}async function compare(){const ids=Array.from(root.querySelectorAll('[data-role=jobs] input:checked')).map(x=>x.value);if(ids.length<2){$('[data-role=status]').textContent='Select at least two runs.';return}try{const b=await api('compare','POST',{projectKey:project(),jobIds:ids});$('[data-role=status]').textContent='Comparison '+b.comparisonHash.slice(0,12)+' · no automatic winner selected';$('[data-role=cards]').innerHTML=b.jobs.map(j=>'<div class="scwb-v880-card"><b>'+esc(j.label||j.jobId)+'</b><span>'+esc(j.runtimeKind)+'</span><small><br>'+j.resultMetricCount+' result metrics</small></div>').join('');$('[data-role=metric-head]').innerHTML='<th>Metric</th>'+b.jobs.map(j=>'<th>'+esc(j.label||j.jobId)+'</th>').join('');$('[data-role=metrics]').innerHTML=(b.resultMetricMatrix.rows||[]).slice(0,80).map(r=>'<tr><td>'+esc(r.metric)+'</td>'+b.jobs.map(j=>'<td>'+esc(r.values[j.jobId]??'—')+'</td>').join('')+'</tr>').join('');$('[data-role=pairs]').innerHTML=(b.pairwiseComparisons||[]).map(p=>'<div class="scwb-v880-pair"><b>'+esc(p.leftJobId)+' → '+esc(p.rightJobId)+'</b> · '+p.metrics.resultMetrics.commonMetricCount+' common result metrics · winner selected: no</div>').join('');}catch(e){$('[data-role=status]').textContent='Error: '+e.message}}$('[data-action=load]').addEventListener('click',load);$('[data-action=compare]').addEventListener('click',compare);if(project())load()})();</script>
<?php return ob_get_clean();}
add_shortcode('sc_workbench_comparative_analysis','scwb_v880_compare_shortcode');
add_action('rest_api_init',function(){register_rest_route('sc-workbench/v1','/comparative-analysis/jobs/(?P<project>[A-Za-z0-9._:-]+)',array('methods'=>'GET','permission_callback'=>'__return_true','callback'=>function($req){return rest_ensure_response(scwb_v880_backend_request('/comparative-analysis/jobs/'.rawurlencode($req['project'])));}));register_rest_route('sc-workbench/v1','/comparative-analysis/compare',array('methods'=>'POST','permission_callback'=>'__return_true','callback'=>function($req){$body=$req->get_json_params();$result=scwb_v880_backend_request('/comparative-analysis/compare','POST',is_array($body)?$body:array());$status=isset($result['_httpStatus'])?(int)$result['_httpStatus']:200;unset($result['_httpStatus']);return new WP_REST_Response($result,$status);}));});
